body:
{
  "pains": [
    {
      "id": "pain:notes-follow-me-home",
      "statement": "I finish the day and the notes are still waiting, so I'm writing them at home at night.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "The patients are done and the notes are not; the chart list at the end of the day is still open.",
        "operational": "The notes get carried home or pushed into the next morning, and on a busy day that is an hour or more of writing after the shift has ended.",
        "personal": "The writing happens at home, after the day has officially finished, and it takes the bedside teaching and the family updates with it."
      },
      "workflow": "The daily progress note in the EHR: written in the gaps between rounds, pushed past the last patient of the day, and finished on a laptop at home at night.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The annual burnout number lands in front of leadership: 51.9% of ambulatory clinicians burned out before an ambient scribe was switched on.",
          "cites": ["src:16"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Sometimes there's just too much patient care- I frequently do notes at home … on a very busy day, as much as an hour or more at home.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "I find it frustrating that writing notes takes so long. And that means there's just less time to actually do bedside teaching, patient updates with family members, and such.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "I personally care a lot about the progress notes and the accuracy and quality of the notes and so I spend quite a bit of time on them on a daily basis when I'm in ICU.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "An hour or more of the evening on a busy day, plus the teaching and the family conversations that do not happen while the notes are being written.",
          "fears": "That the backlog never clears, and every busier day simply moves more of it into the night.",
          "dream_outcome": "Walking out with the notes closed: one attending describes wanting the draft already waiting when rounds end, needing only minor edits before signing."
        }
      },
      "segments": ["seg:system"],
      "feature_ref": "feat:clinician",
      "cites": ["src:3", "src:1"]
    },
    {
      "id": "pain:screen-between-us",
      "statement": "I'm supposed to be listening to the patient, and instead I'm typing and clicking, so I don't hear everything.",
      "element": "b2b:ease_of_doing_business:connection",
      "shape": {
        "surface": "Eye contact goes to the screen while the patient is still talking.",
        "operational": "The clinician types through the visit, loses the thread launching one thing after another, and still goes back to the note afterwards.",
        "personal": "To the patient they look like someone doing their paperwork rather than paying attention, which is how one clinician describes the difference the moment it stops."
      },
      "workflow": "The exam room and the ICU bedside: the clinician at the workstation typing the history while the patient is still describing the symptom, clicking between results and orders in the same minutes the patient is speaking.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "An ambient tool is switched on across the clinic after a pilot, and every clinician has to decide, patient by patient, whether the laptop stays between them.",
          "cites": ["src:14"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I'm supposed to be listening, but I don't hear everything",
              "cites": ["src:2"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "[I] get lost as I'm trying to like look them [patients] in the eye, look at the computer, launch this, launch that, check result",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Every minute I spend writing my notes is time that I'm not spending at the bedside.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "I feel like I can be more face-to-face with them and [have] more eye contact. I feel like I can establish a better relationship instead of staring at the computer and looking like I'm doing all my work and not paying attention to them.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "The parts of the history that get missed while they are looking somewhere else, and the relationship they say they can build when they are not.",
          "fears": "That the thing they missed while typing was the thing that mattered.",
          "dream_outcome": "Being face to face for the whole visit, and having the note come out of the conversation rather than competing with it."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:2", "src:3", "src:1"]
    },
    {
      "id": "pain:editing-instead-of-writing",
      "statement": "The draft comes back long and in somebody else's voice, so now I'm editing a note instead of writing one, and some days that's slower than doing it myself.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "The generated note is verbose in the history, blunt in the assessment, and does not sound like the person who has to sign it.",
        "operational": "They rework the top of the note, cut the non-pertinent detail, and for some patients skip the tool and go back to their own short free text.",
        "personal": "They sign a note that does not read like them: one clinician says flatly that it is not their voice, and takes it anyway to get the note done."
      },
      "workflow": "Reviewing the AI draft in Epic before signing: reading the HPI for padding, rewriting the assessment and plan into their own wording, and deciding per patient whether the draft beats free text at all.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The pilot becomes a commercial rollout and clinicians who never chose the tool inherit its draft.",
          "cites": ["src:14"]
        },
        {
          "event": "A visit type the clinician already knows will produce a wall of text, so the decision to avoid the tool is made before the patient is in the room.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "It's probably actually taking me longer now because I'm doing more editing in the top part of my note than I would have done before.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Because what it does is, in the history section, it's too verbose.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "So there would be patients that I just knew it was going to end up being a massive block of text if I use the tool. And I would much rather go in with my own free text, like short form documentation.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "It's not my voice, right? [The ambient scribe] is a very different voice from my voice. My notes have a certain voice…",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "for everybody, I think the biggest barrier is how do I get it to look and sound the way I want it to",
              "cites": ["src:2"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "It takes you 5 minutes to read through what happened in the last consultation, when it normally take[s] me in 20 seconds",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "And on this occasion this software made my life harder rather than easier",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "The minutes the draft was supposed to save, spent reading and rewriting instead: five minutes to review what used to take twenty seconds.",
          "fears": "That the tool they were told would give them their evenings back has simply changed what the evening is spent on.",
          "dream_outcome": "A draft short enough and close enough to their own wording that signing it is a read, not a rewrite."
        }
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "feature_note": "feat:clinician is the feature this pain lives inside: the draft it produces is the thing being edited. What these clinicians describe wanting is control of length and voice before the draft arrives, and nothing in the company artifact names that.",
      "cites": ["src:1", "src:2", "src:6", "src:13"]
    },
    {
      "id": "pain:read-every-line-before-i-sign",
      "statement": "I read every line before I sign it, because I've seen it put things in the note that were never said.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Misheard words, homonyms, and occasionally diagnoses or exam findings that were never discussed, sitting in a note that looks finished.",
        "operational": "Every draft is checked line by line against what actually happened before it is signed, and nothing is allowed to file itself.",
        "personal": null,
        "personal_note": "No source in this sweep shows what carrying that check costs the clinician personally. The quotes stop at the check itself. Looked through the UCLA ICU interviews, the Stanford interviews and the Iowa interviews; none describe what happens after a note is signed."
      },
      "workflow": "The minute before signing in the EHR: reading the generated note against the encounter or the round, fixing what was misheard, and deciding whether this draft can be trusted enough to sign at all.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Ambient documentation moves out of the clinic and into the ICU, where the note carries a goals-of-care conversation and a wrong line travels further.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "I would have to edit it … I never trust an AI. How accurate is it?",
              "cites": ["src:3"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "There's no way I would want it to automatically put in a note without me reviewing it.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "If it can provide a clear summary with minimal editing- yes I would use it. If not, I probably wouldn't use it.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "It makes mistakes and typos and hears things wrong, occasionally homonyms and other things and I have to fix it because it sounds funny.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "The review cannot be skipped, so the floor on the time per note is set by reading rather than by writing.",
          "fears": "That a polished, complete-looking note gets skimmed instead of scrutinised, and something that was never said ends up signed into the record.",
          "dream_outcome": "A draft they can check quickly because they can see what it was built from, and a clear summary that needs minimal editing."
        }
      },
      "segments": ["seg:system"],
      "feature_ref": null,
      "feature_note": "Nothing in the company artifact addresses verification. feat:clinician writes the draft; no listed feature shows the clinician where a line came from, or flags what the conversation did not contain. Until something does, the check stays manual and this pain stays whoever they buy from.",
      "cites": ["src:3", "src:1", "src:13"]
    },
    {
      "id": "pain:rounds-never-reach-the-note",
      "statement": "Everything we work out on rounds gets said out loud, and then most of the reasoning never makes it into the note.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "The progress note carries the plan but not why the team chose it, and the verbal handoff has no note behind it at all.",
        "operational": "The reasoning gets repeated out loud at each handoff and rebuilt later from memory; an audit of surgical ward rounds found nearly a third of the major spoken decisions missing from the written record.",
        "personal": null,
        "personal_note": "No source shows what the loss costs the individual. The ICU interviews describe what it costs the team and the record, not the person carrying it; nobody in these sources says what it is like to be the one who forgot."
      },
      "workflow": "ICU and surgical rounds at the bedside with the whole team, then the resident or attending writing the progress note afterwards from memory, and the shift-change handoff that is spoken and never written down.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:nursing",
      "triggers": [
        {
          "event": "The system extends ambient documentation past the clinic into inpatient care, where the conversation to be documented has five people in it rather than two.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "There really is a group discussion … why we're thinking what we're thinking and why we're doing what we're doing … there's definitely things lost in how that gets translated to the progress note.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "Those discussions are very rich. They're very comprehensive … But the richness of the discussion frequently does not get translated into a note that I'm writing or sometimes even what the resident writes.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "The thing with the handoffs is there's no documentation whatsoever right now. There are a lot of details that you've discussed verbally, but probably should be in a note.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "The next shift starts without the reasoning, so it gets explained again out loud, and the record is thinner than the care that was given.",
          "fears": "That the detail which was only ever spoken is the one someone needed at three in the morning.",
          "dream_outcome": "The round itself becomes the note: a goals-of-care conversation or a handoff turned into something high quality enough to review and sign."
        }
      },
      "segments": ["seg:system", "seg:nursing"],
      "feature_ref": "feat:nursing",
      "feature_note": "feat:nursing is the closest thing in the artifact, since it drafts from natural conversation, but every product description here is framed around a clinician and a patient. The conversation these clinicians want captured is a team of five talking to each other, and nothing in the artifact says it handles that.",
      "cites": ["src:3", "src:7"]
    },
    {
      "id": "pain:chart-or-keep-him-alive",
      "statement": "When the patient is crashing I'm not charting, so the record gets built back afterwards from what I can remember.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Flowsheet rows sit empty through the sick hours of a shift, then fill in a block at the end.",
        "operational": "Nurses triage what has to be charted in real time and back-chart the rest later; some write the physical assessment before they have done it.",
        "personal": "Being texted by a manager about one unchecked box on a shift spent keeping someone alive is, in one nurse's words, tough mentally on nurses."
      },
      "workflow": "The EHR flowsheet across a 12-hour inpatient shift: complex assessment rows, bath charting and safety rounds deferred while a drip is being titrated, then back-charted at the end of the shift.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Staffing thins and the ratio goes up, and documentation is the first thing that gives.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I want to keep my patient alive. I know listening and charting the S1 and S2 sounds are important, but right now, I have to keep him alive…",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "we are being texted by managers about … not charting one small little thing that had happened throughout your 12hour shift while taking care of patient, I think it is tough mentally on nurses",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I will have plenty of opportunity to back-chart and provide contextual details once I know my patient's needs are met.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "When my patient was critical, I couldn't document until after the shift.",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "Sometimes there's repetition… it takes time, and that's why some nurses write the physical assessment before actually doing it.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "The end of the shift, spent reconstructing hours that were already worked, and a record that is thinner and later than the care it describes.",
          "fears": "That something charted from memory hours afterwards is wrong, or that the box nobody had time for is the one a manager picks up.",
          "dream_outcome": "The charting comes out of the shift as it happens, so what was done at the bedside is what is in the record without a second pass."
        }
      },
      "segments": ["seg:nursing"],
      "feature_ref": "feat:nursing",
      "feature_note": "feat:nursing drafts from natural conversation, which is the talk at the bedside during exactly those hours. Nothing in the artifact says it fills flowsheet rows, and the flowsheet is what actually gets deferred.",
      "cites": ["src:4", "src:5", "src:8"]
    },
    {
      "id": "pain:charting-for-court",
      "statement": "I over-document to protect my license, because if it isn't charted it didn't happen.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "Detail goes into the chart that has no clinical reader, on the chance that a lawyer reads it in two years.",
        "operational": "Defensive charting stacked on top of the required rows, and a running mental check for the one thing that was missed.",
        "personal": "The fear sits over the whole shift: one nurse describes the looming threat that forgetting a single entry means being in trouble, in court, and possibly losing the license."
      },
      "workflow": "End-of-shift charting in the EHR: going back over the flowsheet and the narrative note to add what might be needed in court, and checking that nothing is missing that a manager or an attorney could point at later.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "An accreditation or regulatory requirement lands and adds paperwork on top of what was already required.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I tend to over document. I don't know if you can over document, but I tend to document a lot just to protect myself.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "like kind of chart for court basically.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "that frustration and feeling that I forgot to chart this one thing I'm gonna get in trouble now…that looming thread [of fear]",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "I document anything risky and report it to protect myself.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Time spent writing for an audience that is not clinical, and the low background fear that never fully leaves the shift.",
          "fears": "Being pulled into court two years later with only the chart standing between them and their license.",
          "dream_outcome": "A record that is defensible without having to be padded, so protecting themselves and caring for the patient stop competing."
        }
      },
      "segments": ["seg:nursing"],
      "feature_ref": null,
      "feature_note": "No feature in the artifact touches why the extra charting exists. feat:nursing could make defensive detail cheaper to produce, but what these nurses describe wanting is fewer required rows, which is a policy decision inside the health system rather than a product.",
      "cites": ["src:4", "src:5", "src:8"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Clinicians in these sources are not asking whether ambient documentation exists; they are weighing a named draft against their own free text, per patient and per visit type. That is solution-aware and not yet product-aware: they compare the category to their own habits rather than one vendor to another.",
      "cites": ["src:1", "src:2"]
    },
    "seg:system": {
      "level": "product",
      "rationale": "Large systems in these sources have run a pilot and then an enterprise rollout of a named product, so the buying conversation is past whether to try one; a Duke surgeon writes publicly about a pilot and commercial rollout he took part in, and the Iowa study interviews pilot participants and enterprise-rollout users separately.",
      "cites": ["src:14", "src:2"]
    },
    "seg:nursing": {
      "level": "problem",
      "rationale": "Nurses name the burden in detail and describe the workarounds around it, but no nurse in these sources names an ambient tool as the answer; where nurses do appear in the ambient conversation it is about consent and about tools built for physicians.",
      "cites": ["src:4", "src:5"]
    }
  },
  "stats": [
    {
      "id": "stat:pajama-time",
      "stat": "Primary care physicians average at least 56 minutes of after-hours EHR work for every 8 scheduled patient hours.",
      "scope": "Epic Signal 'Pajama Time' across 195 academic primary care physicians at one US health system, February to July 2025. An earlier national family-medicine figure puts it at 86 minutes a night; the two measures are defined differently, so the lower number is used here.",
      "cites": ["src:9", "src:10"]
    },
    {
      "id": "stat:nurse-share-of-shift",
      "stat": "Nurses spend at least 19% of their time documenting in the EHR.",
      "scope": "US inpatient nursing. AHRQ puts the range at 19 to 35 percent of nursing time, and an AMIA flowsheet analysis puts it at nearly 25% of a shift interacting with the EHR; the bottom of the lower range is used here.",
      "cites": ["src:11", "src:12"]
    }
  ],
  "keywords": [
    "notes at home",
    "pajama time",
    "charting after my shift",
    "back-charting",
    "AI note too verbose",
    "AI note doesn't sound like me",
    "editing AI scribe notes",
    "shorten ambient scribe note",
    "ambient scribe accuracy",
    "AI scribe made up a diagnosis",
    "do I have to review every AI note",
    "ambient scribe for ICU rounds",
    "AI scribe for procedures",
    "charting for court",
    "nursing documentation burden",
    "flowsheet charting time"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the first call with the last ten health systems that bought, which of these pains did they name first, and who named it - the CMIO paying for it or the clinician living with it?",
      "why": "Every pain in this map is voiced by an end user. No economic buyer, champion or blocker is quoted anywhere, because the public record has clinicians talking and system executives mostly not. Without their words the map cannot say how the same pain sounds in a budget conversation.",
      "would_change": "pains[].who_feels and pains[].by_role, adding economic_buyer and champion entries with their own says[]"
    },
    {
      "id": "q:pains-personal-rung",
      "question": "When a clinician tells you what documentation actually costs them - not their day, them - what words do they use?",
      "why": "The personal rung is the one that sells and the one nobody writes down in public. Two pains here carry a null personal rung because no source showed it, and inventing it would put a feeling in a clinician's mouth.",
      "would_change": "pains[].shape.personal on pain:read-every-line-before-i-sign and pain:rounds-never-reach-the-note"
    },
    {
      "id": "q:pains-billing",
      "question": "Do your customers complain that ambient notes fail to support the level of service they billed, and has anyone ever shown you a downcoding, denial or audit number from it?",
      "why": "feat:rcm is in the company artifact and no pain in this map points at it. The only source found claiming ambient notes are structurally poor at documenting medical decision making is one opinion column with unsourced dollar figures, which is one source, so it is a question rather than a row.",
      "would_change": "adds a pain with element b2b:functional:improved_top_line and feature_ref feat:rcm, or leaves the silence standing for positioning"
    },
    {
      "id": "q:pains-specialty-template",
      "question": "Which specialties have told you their own template was already faster than the draft, and what did they say when they stopped using it?",
      "why": "Three participants in one study said their pre-built templates and Epic workflow made the tool more burdensome, not less. One URL is an anecdote, not a pattern, so no row was written for it even though seg:specialty is a named segment.",
      "would_change": "adds a pain with element b2b:ease_of_doing_business:configurability scoped to seg:specialty"
    },
    {
      "id": "q:pains-nursing-us",
      "question": "What do your nursing customers say the charting costs them on a shift, in their own words, and is court and licensing the fear you hear too?",
      "why": "Both nursing rows lean on one US Midwest academic centre study plus one from teaching hospitals in Saudi Arabia. The second source is an adjacent setting, which is why both rows are medium rather than high.",
      "would_change": "pains[].confidence on pain:chart-or-keep-him-alive and pain:charting-for-court"
    },
    {
      "id": "q:pains-cds-signals",
      "question": "Has a customer ever asked for guidance during the visit, or for follow-up to be flagged out of the conversation, or were feat:cds and feat:signals built ahead of the ask?",
      "why": "Nothing in this sweep shows a buyer or a clinician naming either as a problem they have. That silence is either a gap in where I looked or a feature in search of a problem, and only the founder can say which.",
      "would_change": "adds a pain with feature_ref feat:cds or feat:signals, or confirms the silence for the positioning step"
    },
    {
      "id": "q:pains-awareness-nursing",
      "question": "When nursing leaders come to you, are they asking for an ambient tool by name, or asking how to cut the number of required rows?",
      "why": "seg:nursing is set to problem-aware on the basis that no nurse in these sources names an ambient tool as the answer. If nursing leadership arrives asking for Abridge by name, the angles for that segment are written at the wrong stage.",
      "would_change": "awareness['seg:nursing'].level"
    }
  ],
  "sources": [
    {
      "id": "src:1",
      "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11933996/",
      "title": "Physician Perspectives on Ambient AI Scribes",
